const input = $input.first().json.body || $input.first().json;

// Validate required fields
const required = ['company_name', 'contact_name', 'contact_email'];
const missing = required.filter(f => !input[f]);

if (missing.length > 0) {
  return [{ json: { valid: false, error: `Missing required fields: ${missing.join(', ')}` } }];
}

// Sanitize and structure
const client = {
  valid: true,
  client_id: 'CLIENT-' + Date.now().toString(36).toUpperCase(),
  company_name: String(input.company_name || '').trim(),
  contact_name: String(input.contact_name || '').trim(),
  contact_email: String(input.contact_email || '').trim().toLowerCase(),
  phone: String(input.phone || '').trim(),
  contract_size: String(input.contract_size || 'unknown').trim(),
  employee_count: parseInt(input.employee_count) || 0,
  ai_systems: String(input.ai_systems || '').split(',').map(s => s.trim()).filter(Boolean),
  primary_agency: String(input.primary_agency || '').trim(),
  compliance_concerns: String(input.compliance_concerns || '').trim(),
  timeline: String(input.timeline || 'standard').trim(),
  onboarded_at: new Date().toISOString(),
  status: 'intake'
};

return [{ json: client }];

